    let recognition=null,voiceBusy=false,voiceTargetId="",voiceStartedOnce=false;function isFileMode(){return location.protocol==="file:"}function voiceHelp(needsSpeaker=false){let base=needsSpeaker?`語音轉文字後，會以「${src(actor()).name}」送出；請確認內容再送出。`:"語音轉文字後，請確認內容再送出。";return isFileMode()?base+" 目前是 file:// 離線測試，Chrome 可能每次錄音都重新詢問麥克風權限；若出現此情況，請以文字輸入為主，STT 改到 localhost 或 HTTPS 測試。":base}function setVoiceStatus(msg){let el=$("voiceStatus");if(el)el.textContent=msg}function initVoice(){if(recognition)return recognition;const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return null;recognition=new SR();recognition.lang="zh-TW";recognition.interimResults=false;recognition.continuous=false;recognition.onresult=e=>{let target=$(voiceTargetId);if(target){target.value=e.results[0][0].transcript;target.dispatchEvent(new Event("input",{bubbles:true}));target.dispatchEvent(new Event("change",{bubbles:true}))}setVoiceStatus("已轉成文字，請確認內容後再送出。")};recognition.onerror=()=>{voiceBusy=false;S.recordingBy="";setVoiceStatus(isFileMode()?"語音辨識沒有成功。你目前用 file:// 離線測試，若 Chrome 反覆要求權限，請先改用文字輸入，STT 留到 localhost 或 HTTPS 測試。":"語音辨識沒有成功，請再試一次或改用文字。")};recognition.onend=()=>{voiceBusy=false;S.recordingBy="";setVoiceStatus("已結束聆聽，請確認文字後再送出。")};return recognition}function startVoice(id){if(id==="newText"&&!hasSpeaker()){remindSpeaker();return}let target=$(id);if(!target)return;let rec=initVoice();if(!rec){setVoiceStatus("這個瀏覽器目前不支援語音辨識，請改用文字輸入。");return}if(voiceBusy){setVoiceStatus("目前正在聽，請先說完這一段。");return}voiceTargetId=id;voiceBusy=true;voiceStartedOnce=true;S.recordingBy=actor();setVoiceStatus(isFileMode()?"正在聽，說完請稍等轉文字。提醒：file:// 離線模式下，Chrome 可能每次錄音都要求麥克風權限。":"正在聽，說完請稍等轉文字。");render();try{rec.start()}catch(e){voiceBusy=false;S.recordingBy="";setVoiceStatus("語音輸入尚未結束，請稍後再試。")}}
    function render(){saveRoom();document.title="魚骨洞天";let teacher=$("teacherPanel"),preview=$("preview"),prevBtn=$("prevBtn"),nextBtn=$("nextBtn");$("stepNum").textContent=S.step===0?"起始頁":S.step+"/19";$("bar").style.width=(S.step===0?0:S.step/19*100)+"%";if(prevBtn)prevBtn.style.display=S.step<=1?"none":"";if(nextBtn)nextBtn.style.display=S.step>=19?"none":"";if(S.step===0){if(teacher)teacher.style.display="none";if(preview)preview.style.display="none";$("main").innerHTML=screen();return}if(teacher)teacher.style.display="";if(preview)preview.style.display="";$("aiTitle").textContent=stepNames[S.step-1];$("aiText").innerHTML=(ai[S.step]||[]).map(x=>`<p>${x}</p>`).join("");$("ttsToggle").textContent=S.autoTts?"關閉自動朗讀":"開啟自動朗讀";$("agentHint").innerHTML=agentFeedback();$("gateMsg").innerHTML="";$("main").innerHTML=screen();$("preview").innerHTML=collabPanel()+previewFish("right")+previewFish("left");if(!S.ttsReady)setTtsStatus("可按重播提示聆聽老師提示。");else if(S.autoTts&&S.lastSpokenStep!==S.step){S.lastSpokenStep=S.step;speakTeacher(false)}else setTtsStatus("")}
    function panel(title,hint,body){return `<section class="panel">${title||hint?`<div class="panelHead">${title?`<h2>${title}</h2>`:""}${hint?`<p class="hint">${hint}</p>`:""}</div>`:""}${body}</section>`}
    function speakBox(kind,placeholder,buttonText){return `<div class="speakBox"><p class="small">將以「${esc(src(actor()).name)}」送出。</p><textarea id="newText" placeholder="${placeholder}"></textarea><div class="speakControls"><button class="secondary" onclick="startVoice('newText')">語音輸入</button><button onclick="addSpoken('${kind}')">${buttonText}</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(true)}</p></div>`}
    function textAreaWithVoice(id,value,placeholder,onSaveLabel,onSaveCode){return `<div class="speakBox"><textarea id="${id}" placeholder="${placeholder}">${esc(value||"")}</textarea><div class="speakControls"><button class="secondary" onclick="startVoice('${id}')">語音輸入</button><button onclick="${onSaveCode}">${onSaveLabel}</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p></div>`}
    function screen(){if(S.step===0)return step0();return [step1,step2,step3,step4,step5,step6,step7,step8,step9,step10,step11,step12,step13,step14,step15,step16,step17,step18,step19][S.step-1]()}
    function startActivity(){markInteraction();S.lastSpokenStep=0;S.step=1;render()}
    /* Joining now has to succeed on the server before the student is in the
       room: an unknown code no longer quietly creates one. S.joined is set
       first because pollLoop stops while it is false, and rolled back if the
       server turns the code away. */
    async function joinActivity(){
      let name=$("joinName").value.trim(),typed=$("joinRoom").value.trim(),room=canonRoomCode(typed);
      if(!name||!typed){showGate("請先輸入姓名或暱稱與小組房間碼。");return}
      if(room.length<8){showGate("房間碼看起來不正確，請向老師再確認一次。");return}
      /* Switching rooms in place would carry this room's cards into the next
         one: S still holds them, and the first push after joining uploads the
         lot. A reload is the only way that cannot leak one class's writing into
         another class's room. */
      if(S.joined&&room!==S.roomCode){showGate("你目前已經在另一個房間中。請先重新整理頁面再加入新房間，否則這個房間的內容會被帶過去。");return}
      let wasJoined=S.joined,wasRoom=S.roomCode;
      S.nameDraft=name;S.roomCode=room;S.joined=true;S.active=S.selfId;
      /* The local cache is merged before the server's snapshot, not after:
         mergeRoom lets the incoming object win for the fields it does not
         version, so the other order would let a stale device overwrite what the
         group has since confirmed. */
      let outcome=await connectRoom(true,()=>{
        loadRoom(room);
        ensureSource(S.selfId,name,colors[joinedMembers().length%colors.length]);
        S.active=S.selfId;
      });
      if(outcome!=="ok"){
        S.joined=wasJoined;S.roomCode=wasRoom;
        // Leave no half-live session pointing at a room this device is not in.
        SYNC.session=0;SYNC.token="";
        // render() clears the gate message, so it has to come first.
        render();
        showGate(outcome==="not-found"?"找不到這個房間碼，請再確認一次。房間碼由老師建立後提供。":outcome==="rate-limited"?"嘗試次數過多，請稍候一分鐘再試。":"目前連不上小組伺服器，請確認網路後再試一次。");
        /* The attempt stopped the poll loop that was running for the room this
           device was already in. Without this the student keeps working and
           keeps seeing "connected", but never receives another teammate's
           update for the rest of the lesson. */
        if(wasJoined)setTimeout(()=>{if(S.joined&&!SYNC.session)connectRoom()},1200);
        return;
      }
      S.step=2;markInteraction();
      if(roomChannel)roomChannel.postMessage({room:S.roomCode,from:S.selfId,kind:"sync-request"});
      render();schedulePush();
    }
    /* Teachers create the room here and read the code off the projector. Codes
       are generated by the server precisely so that nobody can pick 六年三班. */
    async function createRoom(){
      markInteraction();
      if(location.protocol==="file:"){showGate("目前以 file:// 開啟，無法建立房間。請改用伺服器網址。");return}
      /* Same reason as joinActivity: S.roomCode is read at request time, so
         pointing it at a new room while a session is live would send this
         room's snapshot into the new one. */
      if(S.joined){showGate("你目前已經在房間中。請先重新整理頁面再建立新房間，否則目前房間的內容會被帶進新房間。");return}
      // render() rebuilds Step 1 from state, so keep whatever name was typed.
      let typedName=(($("joinName")||{}).value||"").trim();if(typedName)S.nameDraft=typedName;
      let btn=$("createRoomBtn");if(btn)btn.disabled=true;
      try{
        let res=await fetch(SYNC.base+"api/rooms",{method:"POST",cache:"no-store",headers:{"content-type":"application/json"},body:"{}"});
        if(res.status===429){showGate("建立房間的次數過多，請稍後再試。");return}
        if(!res.ok)throw new Error("HTTP "+res.status);
        let data=await res.json();
        S.roomCode=canonRoomCode(data.room||"");S.createdRoom=data.displayCode||showRoomCode(S.roomCode);
        render();
      }catch(e){showGate("目前無法建立房間，請確認網路後再試一次。")}
      finally{if(btn)btn.disabled=false}
    }
    function step0(){return `<section class="startPanel"><div><p class="eyebrow">創意萬事通</p><h2>魚骨洞天</h2><p>準備好後，按下開始活動。</p><button onclick="startActivity()">開始活動</button></div></section>`}
    function step1(){let selfName=S.joined?src(S.selfId).name:(S.nameDraft||"");return panel("加入活動／加入小組","",`<div class="joinBox"><label>你的姓名或暱稱</label><input id="joinName" value="${esc(selfName==="尚未加入"?"":selfName)}" placeholder="例如：小安"><label>小組房間碼／活動代碼</label><input id="joinRoom" value="${esc(showRoomCode(S.roomCode))}" placeholder="例如：k7m2x-9qpwd"><button onclick="joinActivity()">加入</button>${S.joined?`<p class="joinedNote">已加入 ${esc(showRoomCode(S.roomCode))}，你新增的卡片會標記為 ${esc(src(S.selfId).name)}。</p>`:""}</div><section class="surface"><h3>老師：建立新房間</h3><p class="small">房間碼由伺服器產生，建立後投影給全組抄寫。不再使用自訂代碼，因為班級名稱這類代碼很容易被猜到，而房間裡是同學寫下的生活困擾。</p>${S.createdRoom?`<div class="roomCode">${esc(S.createdRoom)}</div><p class="small">已填入上方欄位。你自己也要輸入姓名後按加入。</p>`:""}<button class="secondary" id="createRoomBtn" onclick="createRoom()">建立新房間</button></section>`)}
    function step2(){let mine=S.distresses.filter(d=>isOwnCard(d));return panel("","",`<section class="surface"><h3>提出我的生活困擾</h3>${speakBox("distress","說出或輸入一個生活中想分析的困擾","確認提出困擾")}</section>${mine.length?`<section class="surface"><h3>我已提出的困擾</h3><div class="cardGrid">${mine.map(d=>distressCard(d)).join("")}</div></section>`:""}`)}
    function groupingProposalCard(p){let revote=groupingNeedsRevote(),chosen=!revote&&voteValue(S.groupingVotes||{},actor())===p.id,counts=voteCounts(S.groupProposals||[],S.groupingVotes||{}),official=S.groupingConfirmed===p.id;return `<article class="card candidateCard ${official?'ok':''}"><div class="meta">${badge(p.source)}<span class="voteCount">${counts[p.id]||0} 票</span>${official?'<span class="badge" style="border-color:#12623d;color:#12623d">正式分群</span>':""}</div><h3>${esc(groupingProposalTitle(p))}</h3>${(p.groups||[]).map(g=>`<div class="surface slim"><strong>${esc(g.name)}</strong><ul>${(g.ids||[]).map(id=>`<li>${esc((S.distresses.find(d=>d.id===id)||{}).text||"困擾")}</li>`).join("")}</ul></div>`).join("")}<div class="voteBar"><button class="${chosen?'selected':'secondary'}" onclick="voteGrouping('${p.id}')">${revote?"重新投這一版":chosen?"已投這一版":"投這一版"}</button></div></article>`}
    function step3(){let count=groupDistressCount();if(count<=1){let waiting=joinedMembers().length>1;return panel("","",`${waiting?'<div class="warn">目前小組困擾池尚未同步到多張困擾，請等待或刷新小組困擾池後再判斷。</div><button class="secondary" onclick="requestRoomSync();render()">刷新小組困擾池</button>':'<div class="confirmedBox">目前只有一張困擾，可以直接進入下一步。</div>'}<div class="cardGrid">${S.distresses.map(d=>distressCard(d)).join("")}</div>`)}ensureDraftGrouping();let ungrouped=S.distresses.filter(d=>!S.draftAssignments[d.id]);return panel("","",`${S.groupingConfirmed?'<div class="confirmedBox">已選出正式分群，可以進入下一步。</div>':""}<section class="surface"><h3>小組困擾卡池</h3><div class="cardGrid">${S.distresses.map(d=>mini("distress",d)).join("")}</div></section><section class="surface"><h3>我的分群草稿</h3><div class="add"><input id="add-draft-topic" placeholder="主題名稱"><button class="secondary" onclick="startVoice('add-draft-topic')">語音輸入</button><button onclick="addDraftTopic()">新增主題</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p><div class="columns classifyColumns"><div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'topic','')"><h3>尚未分群</h3>${ungrouped.map(d=>mini("distress",d)).join("")||'<p class="small">目前沒有未分群困擾。</p>'}</div>${S.draftTopics.map(t=>`<div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'topic','${t.id}')"><div class="classifyControls"><input id="topic-${t.id}" value="${esc(t.name)}" onchange="renameDraftTopic('${t.id}',this.value)"><div class="classifyActions"><button class="secondary" onclick="startVoice('topic-${t.id}')">語音輸入</button><button class="secondary" onclick="removeDraftTopic('${t.id}')">刪除主題</button></div></div>${S.distresses.filter(d=>S.draftAssignments[d.id]===t.id).map(d=>mini("distress",d)).join("")}</div>`).join("")}</div><button onclick="submitGrouping()">提交我的分群結果</button></section><section class="surface"><h3>候選分群版本</h3>${groupingVoteNotice()}<div class="cardGrid">${(S.groupProposals||[]).map(p=>groupingProposalCard(p)).join("")||'<p class="small">還沒有候選分群版本。</p>'}</div></section>`)}
    function step4(){let candidates=problemCandidates();if(!candidates.length)return panel("選擇想分析的問題","",`<p class="warn">請先在 Step 3 確認正式分群。</p>`);return panel("選擇想分析的問題","",`${S.confirmBy.selected?`<div class="confirmedBox">已選出共同問題：${esc(S.selected)}</div>`:""}${voteNotice(candidates,S.problemVotes,"problem")}<div class="cardGrid">${candidates.map(c=>candidateCard(c)).join("")}</div>`)}
    function step5(){ensureProblemDraft();let clear=problemClear(S.selected),s=problemDraftStatus(),mine=voteValue(S.problemDraftVotes||{},actor()),prompt=problemPrompt(),statusMsg=S.problemDraftUpdated?'<p class="warn">主要問題草稿已更新，請重新表態。</p>':(!s.allVoted?'<p class="small">還有成員尚未表態。</p>':s.revise>=s.agree?'<p class="warn">主要問題草稿需要調整，請補充或重新整理後再表態。</p>':'<p class="small">表態完成後，若同意較多會自動進入下一步。</p>'),draftControls=S.problemDraftHold?`<p class="warn">主要問題草稿需要調整。請在上方補充要調整的地方，或按下重新整理草稿後再表態。</p><button onclick="buildProblemDraft()">重新整理主要問題草稿</button>`:`<div class="row wrap"><button class="${mine==='agree'?'selected':'secondary'}" onclick="voteProblemDraft('agree')">${mine==='agree'?'已表態同意':'同意'}</button><button class="${mine==='revise'?'selected':'secondary'}" onclick="voteProblemDraft('revise')">${mine==='revise'?'已表態需要修改':'需要修改'}</button></div><div class="voteSummary"><span class="voteCount">同意 ${s.agree} 票</span><span class="voteCount">需要修改 ${s.revise} 票</span></div>${statusMsg}`;return panel("界定主要問題","",`<section class="surface"><h3>投票選出的共同問題</h3><p>${esc(S.selected||"尚未選定")}</p>${clear?'<p class="ok">這個共同問題已大致清楚，可以先整理成主要問題草稿。</p>':`<p class="warn">還需要補充一點：${esc(prompt)}</p>`}</section><section class="surface"><h3>補充一點讓問題更清楚</h3><textarea id="problemSupplement" placeholder="${esc(prompt)}"></textarea><div class="speakControls"><button class="secondary" onclick="startVoice('problemSupplement')">語音輸入</button><button onclick="addProblemDetail()">送出補充</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p></section>${S.problemDetails.length?`<section class="surface"><h3>小組補充區</h3><div class="cardGrid">${S.problemDetails.map(d=>problemDetailCard(d)).join("")}</div></section>`:""}<section class="draftBox"><h3>主要問題草稿</h3><p class="small">草稿只整理已提供的內容，確認前不會成為定稿。</p>${S.problemDraft?`<div class="surface"><p>${esc(S.problemDraft)}</p></div>${draftControls}`:`<button onclick="buildProblemDraft()">整理主要問題草稿</button>`}${S.problemOk?'<p class="ok">主要問題已成為定稿，下一步會放到向右魚骨圖的魚頭。</p>':''}</section>`)}
    function intro(side){let isR=side==="right";return panel(isR?"認識向右魚骨圖":"認識向左魚骨圖",isR?"先分析原因，不急著想方法。":"根據決策目標來想方法。",`<div class="introDiagram"><div class="introStack"><div class="introBox"><strong>${isR?"大要因":"大方法"}</strong><p>${isR?"一類相近原因":"一類解決方向"}</p></div><div class="introBox"><strong>${isR?"具體原因":"具體方法"}</strong><p>${isR?"更細的情況、行為或條件":"實際可做的行動"}</p></div></div><div><div class="fishMiniHead">${isR?"魚頭：主要問題":"魚頭：決策目標"}</div><div class="fishLine"></div></div><div class="introBox"><strong>${isR?"魚骨上的內容都要回答：「為什麼？」":"魚骨上的內容都要回答：「可以怎麼做？」"}</strong><p>${isR?"每張原因之後會被整理到大要因下面。":"每個方法之後要連回原因，才可放進魚骨圖。"}</p></div></div>${fish(side)}`)}
    function step6(){let problem=S.problem||S.selected||"目前已確認的主要問題",groups=[{name:"大骨：一類相近原因",items:["原因卡：較具體的原因","原因卡：更細的情況"]},{name:"大骨：另一類原因",items:["原因卡：行為或條件"]},{name:"大骨：還可以有其他原因類別",items:["原因卡：較具體的原因"]}];return panel("認識向右魚骨圖","",`<div class="rightDemo">${fishboneMarkup("right",groups,problem,"向右魚骨圖示意：找原因","魚頭＝目前主要問題","","具體原因",true)}</div><p class="warn"><strong>提醒：</strong>每張原因卡都要能回答：為什麼會發生這個主要問題？</p>`)}
    function step7(){let mine=S.causes.filter(c=>c.status!=="已移到方法暫存區"&&isOwnCard(c));return panel("提出可能原因","",`<section class="surface"><h3>提出我的原因</h3>${speakBox("cause","說出或輸入一個可能原因","確認提出原因")}</section>${mine.length?`<section class="surface"><h3>我已提出的原因</h3><div class="cardGrid">${mine.map(c=>causeCard(c,false)).join("")}</div></section>`:""}`)}
    function step8(){let st=causeHandlingDone();return panel("確認原因內容","",`<section class="surface"><h3>處理進度</h3><p class="${st.ok?'ok':'small'}">已處理 ${st.done}/${st.total} 張原因卡</p></section><section class="surface"><h3>小組原因池</h3><div class="cardGrid">${S.causes.filter(c=>c.status!=="已移到方法暫存區").map(c=>causeCard(c,true)).join("")||'<p class="small">還沒有原因卡。</p>'}</div></section><h3>方法暫存區</h3><div class="cardGrid">${S.stash.map(m=>`<article class="card"><p>${esc(m.text)}</p>${badge(m.source)}</article>`).join("")||'<p class="small">像方法的內容會先暫放在這裡。</p>'}</div>`)}
    function step9(){let causes=usableCauses();if(!causes.length)return panel("原因分類與大要因命名","",`<p class="warn">請先在 Step 8 確認至少一張原因卡。</p>`);ensureDraftCauseClass();let ungrouped=causes.filter(c=>!S.draftCauseAssignments[c.id]);return panel("原因分類與大要因命名","",`${S.causeClassConfirmed?'<div class="confirmedBox">已選出正式原因分類，可以進入下一步。</div>':""}<section class="surface"><h3>已確認為原因的卡片</h3><div class="cardGrid">${causes.map(c=>mini("cause",c)).join("")}</div></section><section class="surface"><h3>我的原因分類草稿</h3><div class="add"><input id="add-draft-cat" placeholder="大要因名稱"><button class="secondary" onclick="startVoice('add-draft-cat')">語音輸入</button><button onclick="addDraftCat()">新增大要因</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p><div class="columns classifyColumns"><div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'cat','')"><h3>尚未分類原因</h3>${ungrouped.map(c=>mini("cause",c)).join("")||'<p class="small">目前沒有未分類原因。</p>'}</div>${S.draftCats.map(cat=>`<div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'cat','${cat.id}')"><div class="classifyControls"><input id="draft-cat-${cat.id}" value="${esc(cat.name)}" onchange="renameDraftCat('${cat.id}',this.value)"><div class="classifyActions"><button class="secondary" onclick="startVoice('draft-cat-${cat.id}')">語音輸入</button><button class="secondary" onclick="removeDraftCat('${cat.id}')">刪除大要因</button></div></div>${causes.filter(c=>S.draftCauseAssignments[c.id]===cat.id).map(c=>mini("cause",c)).join("")}</div>`).join("")}</div><button onclick="submitCauseClass()">提交我的原因分類</button></section><section class="surface"><h3>候選原因分類版本</h3><p class="small">你覺得哪一版原因分類最適合放進向右魚骨圖？</p>${causeClassVoteNotice()}<div class="cardGrid">${(S.causeClassProposals||[]).map(p=>causeClassProposalCard(p)).join("")||'<p class="small">還沒有候選原因分類版本。</p>'}</div></section>`)}
    function step10(){return panel("確認向右魚骨圖","",fish("right")+rightVoteNotice()+`${S.rightOk?'<p class="ok">向右魚骨圖已確認。</p>':''}${confirmLine('right','向右魚骨圖')}`)}
    function step11(){ensureGoalDraft();let s=goalDraftStatus(),mine=voteValue(S.goalDraftVotes||{},actor()),prompt=goalPrompt(),ownStatus=mine==="agree"?"你已同意":mine==="revise"?"你選擇需要修改":"你尚未表態",statusMsg=S.goalDraftUpdated?'<p class="warn">決策目標草稿已更新，請重新表態。</p>':(!s.allVoted?'<p class="small">還有成員尚未表態。</p>':s.revise>=s.agree?'<p class="warn">決策目標草稿需要調整。需要修改的成員可以新增補充或修改自己的想法，草稿更新後大家再重新表態。</p>':'<p class="small">表態完成後，若同意較多會自動進入下一步。</p>'),draftControls=S.goalDraftHold?`<p class="warn">決策目標草稿需要調整。需要修改的成員可以新增補充或修改自己的想法；不需要每個人都補充。</p><button onclick="buildGoalDraft()">重新整理決策目標草稿</button>`:`<p class="small">${ownStatus}。已表態 ${s.total}/${s.totalMembers} 人。</p><div class="row wrap"><button class="${mine==='agree'?'selected':'secondary'}" onclick="voteGoalDraft('agree')">${mine==='agree'?'你已同意':'同意'}</button><button class="${mine==='revise'?'selected':'secondary'}" onclick="voteGoalDraft('revise')">${mine==='revise'?'你選擇需要修改':'需要修改'}</button></div><div class="voteSummary"><span class="voteCount">同意 ${s.agree} 票</span><span class="voteCount">需要修改 ${s.revise} 票</span></div>${statusMsg}`;return panel("建立決策目標","",`${rightSummary()}<section class="surface"><h3>提出決策目標想法</h3><textarea id="goalIdea" placeholder="${esc(prompt)}"></textarea><div class="speakControls"><button class="secondary" onclick="startVoice('goalIdea')">語音輸入</button><button onclick="addGoalIdea()">送出想法</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p></section>${S.goalIdeas.length?`<section class="surface"><h3>小組目標想法區</h3><div class="cardGrid">${S.goalIdeas.map(d=>goalIdeaCard(d)).join("")}</div></section>`:""}<section class="draftBox"><h3>決策目標草稿</h3><p class="small">草稿只整理已提供的目標想法，確認前不會成為正式決策目標。</p>${S.goalDraft?`<div class="surface"><p>${esc(S.goalDraft)}</p></div>${draftControls}`:`<button onclick="buildGoalDraft()">整理決策目標草稿</button>`}${S.goal?'<p class="ok">決策目標已確認，下一步會放到向左魚骨圖的魚頭。</p>':''}</section><details id="priorityDetails" class="surface" ${S.priorityOpen?'open':''} ontoggle="S.priorityOpen=this.open"><summary>可選填：想優先回應的原因</summary><div class="chips">${usableCauses().map(c=>`<label class="chip"><input type="checkbox" ${(S.priority||[]).includes(c.id)?"checked":""} onchange="togglePriority('${c.id}',this.checked)">${esc(c.text)}</label>`).join("")||'<p class="small">先完成原因分析後，這裡會出現可選原因。</p>'}</div></details>${confirmLine('goal','決策目標')}`)}
    function step12(){let goal=S.goal||"目前已確認的決策目標",groups=[{name:"大方法：一類解決方向",items:["方法卡：實際可做的行動","方法卡：更細的步驟"]},{name:"大方法：另一類方法",items:["方法卡：所需資源或做法"]},{name:"大方法：還可以有其他方法類別",items:["方法卡：實際可做的行動"]}];return panel("認識向左魚骨圖","",`<div class="rightDemo">${fishboneMarkup("left",groups,goal,"向左魚骨圖示意：找方法","魚頭＝目前決策目標","","具體方法",true)}</div><p class="warn"><strong>提醒：</strong>每個方法都要能說明：它回應哪個原因，又如何幫助達成決策目標？</p>`)}
    function step13(){let mine=S.methods.filter(m=>isOwnCard(m)&&m.status!=="正式方法"),ownStash=S.stash.filter(m=>canEditCard(m));return panel("提出解決方法","",`<section class="surface"><h3>提出我的方法</h3>${speakBox("method","說出或輸入一個可能方法","確認提出方法")}</section>${ownStash.length?`<section class="surface"><h3>我前面暫放的方法</h3><p class="small">可以取回成為自己的候選方法。</p><div class="cardGrid">${ownStash.map(m=>`<article class="card"><p>${esc(m.text)}</p>${audit(m)}<button class="secondary" onclick="takeStash('${m.id}')">取回成為方法卡</button></article>`).join("")}</div></section>`:""}${mine.length?`<section class="surface"><h3>我已提出的方法</h3><div class="cardGrid">${mine.map(m=>methodIdeaCard(m)).join("")}</div></section>`:""}`)}
    function step14(){let st=methodCheckDone();return panel("檢查方法與原因對應","",`<section class="surface"><h3>決策目標</h3><p>${esc(S.goal||"尚未建立")}</p></section>${rightSummary()}<section class="surface"><h3>方法處理進度</h3><p class="${st.ok?'ok':'small'}">已處理 ${st.done}/${st.total} 張方法卡</p></section><section class="surface"><h3>小組方法池</h3><div class="cardGrid">${S.methods.map(methodCheckCard).join("")||'<p class="small">還沒有方法卡。請先回到 Step 13 提出方法。</p>'}</div></section><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p>`)}
    function step15(){let methods=methodClassCandidates();if(!methods.length)return panel("方法分類與大方法命名","",`<p class="warn">請先在 Step 14 完成至少一張方法檢查。</p>`);ensureDraftMethodClass();let ungrouped=methods.filter(m=>!S.draftMethodAssignments[m.id]);return panel("方法分類與大方法命名","",`${S.methodClassConfirmed?'<div class="confirmedBox">已選出正式方法分類，可以進入下一步。</div>':""}<section class="surface"><h3>已完成檢查的方法</h3><div class="cardGrid">${methods.map(m=>mini("method",m)).join("")}</div></section><section class="surface"><h3>我的方法分類草稿</h3><div class="add"><input id="add-draft-method-cat" placeholder="大方法名稱"><button class="secondary" onclick="startVoice('add-draft-method-cat')">語音輸入</button><button onclick="addDraftMethodCat()">新增大方法</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p><div class="columns classifyColumns"><div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'methodClass','')"><h3>尚未分類方法</h3>${ungrouped.map(m=>mini("method",m)).join("")||'<p class="small">目前沒有未分類方法。</p>'}</div>${S.draftMethodCats.map(cat=>`<div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'methodClass','${cat.id}')"><div class="classifyControls"><input id="draft-method-cat-${cat.id}" value="${esc(cat.name)}" onchange="renameDraftMethodCat('${cat.id}',this.value)"><div class="classifyActions"><button class="secondary" onclick="startVoice('draft-method-cat-${cat.id}')">語音輸入</button><button class="secondary" onclick="removeDraftMethodCat('${cat.id}')">刪除大方法</button></div></div>${methods.filter(m=>S.draftMethodAssignments[m.id]===cat.id).map(m=>mini("method",m)).join("")}</div>`).join("")}</div><button onclick="submitMethodClass()">提交我的方法分類</button></section><section class="surface"><h3>候選方法分類版本</h3><p class="small">你覺得哪一版方法分類最適合放進向左魚骨圖？</p>${methodClassVoteNotice()}<div class="cardGrid">${(S.methodClassProposals||[]).map(p=>methodClassProposalCard(p)).join("")||'<p class="small">還沒有候選方法分類版本。</p>'}</div></section>${S.methods.filter(m=>m.status==="暫不納入").length?`<section class="surface"><h3>未納入方法區</h3><div class="cardGrid">${S.methods.filter(m=>m.status==="暫不納入").map(m=>`<article class="card"><p>${esc(m.text)}</p>${audit(m)}</article>`).join("")}</div></section>`:""}`)}
    step15=function(){let methods=methodClassCandidates();if(!methods.length)return panel("方法分類與大方法命名","",`<p class="warn">請先在 Step 14 完成至少一張方法檢查。</p>`);ensureDraftMethodClass();let ungrouped=methods.filter(m=>!S.draftMethodAssignments[m.id]);let columns=`<div class="columns classifyColumns methodClassColumns" ondragover="autoScrollMethodColumns(event)"><div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'methodClass','')"><h3>尚未分類方法</h3>${ungrouped.map(methodClassMini).join("")||'<p class="small">目前沒有未分類方法。</p>'}</div>${S.draftMethodCats.map(cat=>`<div class="drop" ondragover="event.preventDefault()" ondrop="drop(event,'methodClass','${cat.id}')"><div class="classifyControls"><input id="draft-method-cat-${cat.id}" value="${esc(cat.name)}" onchange="renameDraftMethodCat('${cat.id}',this.value)" title="${esc(cat.name)}"><div class="classifyActions"><button class="secondary" onclick="startVoice('draft-method-cat-${cat.id}')">語音輸入</button><button class="secondary" onclick="removeDraftMethodCat('${cat.id}')">刪除大方法</button></div></div>${methods.filter(m=>S.draftMethodAssignments[m.id]===cat.id).map(methodClassMini).join("")||'<p class="small">可拖曳方法卡到這裡，或用卡片上的下拉選單移入。</p>'}</div>`).join("")}</div>`;return panel("方法分類與大方法命名","",`${S.methodClassConfirmed?'<div class="confirmedBox">已選出正式方法分類，可以進入下一步。</div>':""}<section class="surface"><h3>已完成檢查的方法</h3><p class="small">可以拖曳方法卡到大方法分類；如果分類在畫面外，可左右捲動，或直接用卡片上的「移到大方法」下拉選單。</p><div class="cardGrid">${methods.map(methodClassMini).join("")}</div></section><section class="surface"><h3>我的方法分類草稿</h3><div class="add"><input id="add-draft-method-cat" placeholder="大方法名稱"><button class="secondary" onclick="startVoice('add-draft-method-cat')">語音輸入</button><button onclick="addDraftMethodCat()">新增大方法</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p>${columns}<button onclick="submitMethodClass()">提交我的方法分類</button></section><section class="surface"><h3>候選方法分類版本</h3><p class="small">你覺得哪一版方法分類最適合放進向左魚骨圖？</p>${methodClassVoteNotice()}<div class="cardGrid">${(S.methodClassProposals||[]).map(p=>methodClassProposalCard(p)).join("")||'<p class="small">還沒有候選方法分類版本。</p>'}</div></section>${S.methods.filter(m=>m.status==="暫不納入").length?`<section class="surface"><h3>未納入方法區</h3><div class="cardGrid">${S.methods.filter(m=>m.status==="暫不納入").map(m=>`<article class="card"><p>${esc(m.text)}</p>${audit(m)}</article>`).join("")}</div></section>`:""}`)}
    function step16(){return panel("成果整理","",`${doubleFishboneMarkup("雙向魚骨圖成果確認")}${outcomeVoteNotice()}<details><summary>查看輔助文字整理</summary><pre class="outcome helper">${esc(outcomeCore())}</pre></details>${confirmLine('outcome','成果內容')}`)}
    function step17(){let methods=formalMethods(),mine=solutionVoteValue(),feasibleOpts=methods.map(m=>`<option value="${m.id}" ${mine.feasible===m.id?"selected":""}>${esc(m.text)}</option>`).join(""),uniqueOpts=methods.map(m=>`<option value="${m.id}" ${mine.unique===m.id?"selected":""}>${esc(m.text)}</option>`).join("");if(!methods.length)return panel("選擇方案","",`<p class="warn">請先在 Step 15 確認至少一個正式方法。</p>`);return panel("選擇方案","",`<section class="surface"><h3>正式方法清單</h3><div class="cardGrid">${methods.map(m=>`<article class="card formal"><p>${esc(m.text)}</p><p class="small">大方法：${esc(m.big)}</p>${audit(m)}</article>`).join("")}</div></section><section class="surface"><h3>我的方案選擇</h3><label>最可行方法</label><select id="feasiblePick"><option value="">請選擇</option>${feasibleOpts}</select><textarea id="feasibleReason" placeholder="為什麼這個方法最可行？">${esc(mine.feasibleReason||"")}</textarea><button class="secondary" onclick="startVoice('feasibleReason')">語音輸入理由</button><label>最獨特方法</label><select id="uniquePick"><option value="">請選擇</option>${uniqueOpts}</select><textarea id="uniqueReason" placeholder="為什麼這個方法最獨特？">${esc(mine.uniqueReason||"")}</textarea><button class="secondary" onclick="startVoice('uniqueReason')">語音輸入理由</button><button onclick="submitSolutionVote()">送出我的方案選擇</button>${solutionVoteNotice()}</section>${confirmLine('feasible','方案選擇')}<p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p>`)}
    function step18(){let mine=ownReflection(),st=reflectionStatus();return panel("反思","",`<section class="surface"><h3>我的反思</h3><textarea id="reflectionText" placeholder="魚骨圖怎麼幫助你看見問題背後的原因？你在小組整理過程中有什麼新的發現？">${esc((mine||{}).text||"")}</textarea><div class="speakControls"><button class="secondary" onclick="startVoice('reflectionText')">語音輸入</button><button onclick="saveReflection()">確認反思</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p></section><section class="surface"><h3>反思進度</h3><p class="${st.ok?'ok':'small'}">已完成 ${st.done}/${st.total} 位</p>${st.ok?'':'<p class="small">等待其他成員完成反思。</p>'}</section><section class="surface"><h3>小組反思牆</h3><div class="cardGrid">${S.reflections.length?S.reflections.map(reflectionCard).join(""):'<p class="small">目前還沒有成員送出反思。</p>'}</div></section>${S.reflectionSummaryOk?`<section class="summaryBlock"><h3>小組反思摘要</h3><p>${esc(S.reflectionSummary)}</p></section>`:""}${confirmLine('reflection','反思')}`)}
    function step19(){return panel("最終成果呈現與匯出","",`${doubleFishboneMarkup("雙向魚骨圖最終成果")}<div class="finalBlocks">${selectionBlock()}${reflectionBlock()}</div><details><summary>查看各成員個人反思</summary><div class="cardGrid">${S.reflections.map(reflectionCard).join("")}</div></details><details><summary>查看完整文字整理</summary><pre class="outcome helper">${esc(outcomeFull())}</pre></details><div class="row stack"><button onclick="exportImg()">匯出圖片版 SVG</button><button class="secondary" onclick="exportText()">匯出文字版</button></div>`)}
    function addRow(label,ph,type){return `<div class="add"><input id="add-${type}" placeholder="${ph}"><button class="secondary" onclick="startVoice('add-${type}')">語音輸入</button><button onclick="addGroup('${type}')">${label}</button></div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p>`}
    function resetGroupingConfirm(){S.groupProposals=[];newVoteRound("grouping");S.groupConfirmVotes={};S.groupingOwnConcern=false;S.groupingConfirmed="";S.draftAssignments={};S.confirmBy.grouping="";resetProblemChoiceState()}
    function resetCauseClass(){S.causeClassProposals=[];newVoteRound("causeClass");S.causeClassConfirmed="";S.draftCauseAssignments={};S.rightOk=false;S.rightNeedsRevision=false;newVoteRound("right");S.confirmBy.right=""}
    function addGroup(type){let v=$("add-"+type).value.trim();if(!v)return;if(type==="topic"){if(!hasSpeaker()){remindSpeaker();return}S.topics.push({id:uid("t"),name:v});resetGroupingConfirm()}if(type==="cat")S.cats.push({id:uid("cat"),name:v});render()}
    function renameTopic(id,value){let t=S.topics.find(x=>x.id===id);if(t){t.name=value;resetGroupingConfirm()}render()}
    function removeTopic(id){S.topics=S.topics.filter(x=>x.id!==id);S.distresses.forEach(d=>{if(d.groupId===id)d.groupId=""});resetGroupingConfirm();render()}
    function distressCard(d,draggable=false){let editable=isOwnCard(d),dragAttr=draggable?` draggable="true" ondragstart="drag(event,'distress','${d.id}')"`:` draggable="false"`;return `<article class="card"${dragAttr}>${editable?`<textarea id="distressText-${d.id}" onchange="editDistress('${d.id}',this.value)">${esc(d.text)}</textarea>`:`<p>${esc(d.text)}</p>`}${audit(d)}${editable?`<button class="secondary" onclick="startVoice('distressText-${d.id}')">語音輸入</button><button class="secondary" onclick="removeDistress('${d.id}')">刪除</button>`:'<div class="readOnlyNote">這是其他成員提出的困擾，這裡先以唯讀呈現。</div>'}</article>`}
    function causeCard(c,check,draggable=false){let editable=isOwnCard(c);if(!check){let canDrag=draggable&&editable,dragAttr=canDrag?` draggable="true" ondragstart="drag(event,'cause','${c.id}')"`:` draggable="false"`;return `<article class="card"${dragAttr}>${editable?`<textarea id="causeText-${c.id}" onchange="editCause('${c.id}','text',this.value)">${esc(c.text)}</textarea>`:`<p>${esc(c.text)}</p>`}${audit(c)}${editable?`<button class="secondary" onclick="startVoice('causeText-${c.id}')">語音輸入</button><button class="secondary" onclick="removeCause('${c.id}')">刪除</button>`:'<div class="readOnlyNote">這是其他成員提出的原因，這裡先以唯讀顯示。</div>'}</article>`}let ai=classifyCause(c.text),editing=editable&&c.status==="修改中",confirmed=c.status==="已確認為原因",unused=c.status==="暫不使用",stashed=c.status==="已移到方法暫存區",action=ai.kind==="比較像方法"?`<button class="choiceBtn" onclick="moveToStash('${c.id}')">同意 AI 判斷，移到方法暫存區</button>`:ai.kind==="比較像原因"?`<button class="choiceBtn" onclick="confirmCause('${c.id}')">同意 AI 判斷</button>`:`<button class="choiceBtn" onclick="editCause('${c.id}','status','暫不使用')">同意 AI 判斷，暫不使用</button>`;return `<article class="card ${confirmed?'ok':''}">${editing?`<textarea id="causeText-${c.id}">${esc(c.text)}</textarea><div class="row wrap"><button class="choiceBtn" onclick="saveCauseRevision('${c.id}')">儲存並重新判斷</button><button class="secondary" onclick="startVoice('causeText-${c.id}')">語音輸入</button></div>`:`<p><strong>學生原本輸入：</strong>${esc(c.text)}</p>`}${audit(c)}<div class="warn"><strong>AI 初步判斷：</strong>${esc(ai.kind)}<br>${esc(ai.reason)}</div><div class="row wrap">${confirmed?'<span class="badge" style="border-color:#12623d;color:#12623d">已確認為原因</span>':stashed?'<span class="badge" style="border-color:#9a3412;color:#9a3412">已移到方法暫存區</span>':unused?'<span class="badge" style="border-color:#64748b;color:#64748b">暫不使用</span>':editable?action:'<span class="badge" style="border-color:#64748b;color:#64748b">等待原提出者處理</span>'}${editable?`<button class="secondary" onclick="editCause('${c.id}','status','修改中')">我要修改內容</button><button class="secondary" onclick="editCause('${c.id}','status','暫不使用')">暫不使用</button>`:'<div class="readOnlyNote">這是其他成員提出的原因，這裡先以唯讀顯示。</div>'}</div>${confirmed?'<p class="ok">已確認為原因，可進入後續分類。</p>':''}</article>`}
    function mini(type,x){return `<article class="mini" draggable="true" ondragstart="drag(event,'${type}','${x.id}')"><p>${esc(x.text)}</p>${badge(x.source)}</article>`}
    function methodClassOptions(selected){return `<option value="" ${!selected?"selected":""}>尚未分類方法</option>${(S.draftMethodCats||[]).map(c=>`<option value="${c.id}" ${selected===c.id?"selected":""}>${esc(c.name||"未命名大方法")}</option>`).join("")}`}
    function moveMethodClassBySelect(mid,cid){ensureDraftMethodClass();if(cid)S.draftMethodAssignments[mid]=cid;else delete S.draftMethodAssignments[mid];render()}
    function methodClassMini(m){let current=S.draftMethodAssignments[m.id]||"";return `<article class="mini methodClassCardMini" draggable="true" ondragstart="drag(event,'method','${m.id}')" title="${esc(m.text)}"><p>${esc(clampText(m.text,54))}</p>${badge(m.source)}<div class="methodClassMove"><label for="move-method-${m.id}">移到大方法</label><select id="move-method-${m.id}" onchange="moveMethodClassBySelect('${m.id}',this.value)">${methodClassOptions(current)}</select></div></article>`}
    function autoScrollMethodColumns(e){let box=e.currentTarget,r=box.getBoundingClientRect();if(e.clientX<r.left+70)box.scrollLeft-=24;else if(e.clientX>r.right-70)box.scrollLeft+=24}
    function editDistress(id,val){let d=S.distresses.find(x=>x.id===id);if(!d||!isOwnCard(d)){showGate("只能修改自己提出的困擾。");return}d.text=val;setUpdated(d);S.distressesVersion=(S.distressesVersion||0)+1;resetGroupingConfirm();render()} function removeDistress(id){let d=S.distresses.find(x=>x.id===id);if(!d||!isOwnCard(d)){showGate("只能刪除自己提出的困擾。");return}if(confirm("刪除此困擾？")){S.distresses=S.distresses.filter(x=>x.id!==id);S.deletedDistressIds=unionIds(S.deletedDistressIds,[id]);S.distressesVersion=(S.distressesVersion||0)+1;resetGroupingConfirm();render()}}
    function editCause(id,k,v){let c=S.causes.find(x=>x.id===id);if(!c||!isOwnCard(c)){showGate("只能修改自己提出的原因。");return}c[k]=v;setUpdated(c);if(k==="text"){c.aiGuess=classifyCause(v).kind;c.status="待確認";c.catId=""}S.causesVersion=(S.causesVersion||0)+1;resetCauseClass();maybeAdvanceAfterCauseHandling();render()} function confirmCause(id){let c=S.causes.find(x=>x.id===id);if(!c||!isOwnCard(c)){showGate("只能確認自己提出的原因。");return}c.status="已確認為原因";c.aiGuess="比較像原因";setUpdated(c);S.causesVersion=(S.causesVersion||0)+1;resetCauseClass();maybeAdvanceAfterCauseHandling();render()} function saveCauseRevision(id){let c=S.causes.find(x=>x.id===id),el=$("causeText-"+id);if(!c||!isOwnCard(c)){showGate("只能修改自己提出的原因。");return}if(el){c.text=el.value.trim();c.aiGuess=classifyCause(c.text).kind;c.status="待確認";c.catId="";setUpdated(c);S.causesVersion=(S.causesVersion||0)+1;resetCauseClass()}render()} function removeCause(id){let c=S.causes.find(x=>x.id===id);if(!c||!isOwnCard(c)){showGate("只能刪除自己提出的原因。");return}if(confirm("刪除此原因？")){S.causes=S.causes.filter(x=>x.id!==id);S.deletedCauseIds=unionIds(S.deletedCauseIds,[id]);S.causesVersion=(S.causesVersion||0)+1;S.methods.forEach(m=>m.causes=m.causes.filter(c=>c!==id));resetCauseClass();maybeAdvanceAfterCauseHandling();render()}}
    function moveToStash(cid){let c=S.causes.find(x=>x.id===cid);if(!c||!isOwnCard(c)){showGate("只能處理自己提出的原因。");return}S.stash.push({id:uid("stash"),text:c.text,source:c.source,createdBy:c.createdBy||c.source,updatedBy:actor(),from:cid});c.status="已移到方法暫存區";setUpdated(c);S.causesVersion=(S.causesVersion||0)+1;resetCauseClass();maybeAdvanceAfterCauseHandling();render()}
    function takeStash(mid){let m=S.stash.find(x=>x.id===mid);if(!m)return;S.methods.push({id:uid("m"),text:m.text,source:m.source,createdBy:m.createdBy||m.source,updatedBy:actor(),big:"",status:"草稿",causes:[],effect:""});S.methodsVersion=(S.methodsVersion||0)+1;S.stash=S.stash.filter(x=>x.id!==mid);render()}
    function methodIdeaCard(m){let hint=vagueMethod(m)?'<p class="warn">這個方法還有點籠統，可以再補充誰做、什麼時候做、怎麼做。</p>':'<p class="small">這是一個候選方法，下一步再檢查它回應哪個原因。</p>';return `<article class="card methodCard"><textarea id="methodText-${m.id}" onchange="methodEdit('${m.id}','text',this.value)">${esc(m.text)}</textarea>${audit(m)}${hint}<button class="secondary" onclick="startVoice('methodText-${m.id}')">語音輸入</button><button class="secondary" onclick="removeMethod('${m.id}')">刪除</button></article>`}
    function methodEdit(id,k,v){let m=S.methods.find(x=>x.id===id);if(!m||!canEditCard(m)){showGate("只能修改自己提出的方法。");return}m[k]=v;if(["text","effect"].includes(k)&&["已完成檢查","已完成對應檢查","需要修改說明"].includes(m.status)){m.status="草稿";m.checkMsg=""}setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;resetMethodClass();render()}
    function methodEditSoft(id,k,v){let m=S.methods.find(x=>x.id===id);if(m&&canEditCard(m)){m[k]=v;if(["text","effect"].includes(k)&&["已完成檢查","已完成對應檢查","需要修改說明"].includes(m.status)){m.status="草稿";m.checkMsg=""}setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1}}
    function toggleMethodCause(mid,cid,on){let m=S.methods.find(x=>x.id===mid);if(!m||!canEditCard(m)){showGate("只能處理自己提出的方法。");return}m.causes=Array.isArray(m.causes)?m.causes:[];m.causes=on?unionIds(m.causes,[cid]):m.causes.filter(x=>x!==cid);if(["已完成檢查","已完成對應檢查","需要修改說明"].includes(m.status)){m.status="草稿";m.checkMsg=""}setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;resetMethodClass();render()}
    function addCauseLink(mid,cid){if(!cid)return;toggleMethodCause(mid,cid,true)}
    function removeCauseLink(mid,cid){toggleMethodCause(mid,cid,false)}
    function runMethodAiCheck(id){let m=S.methods.find(x=>x.id===id);if(!m||!canEditCard(m))return;let check=reviewMethodAlignment(m);if(!check.ok){m.status="需要修改說明";m.checkMsg=check.msg;setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;resetMethodClass();render();showGate(check.msg);return}m.status="已完成對應檢查";m.checkMsg=check.msg;setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;resetMethodClass();maybeAdvanceAfterMethodCheck();render();showOk(check.msg)}
    function completeMethodCheck(id){let m=S.methods.find(x=>x.id===id);if(!m||!canEditCard(m)){showGate("只能提交自己提出的方法給 AI 檢查。");return}m.text=String(($("methodText-"+id)||{}).value||m.text||"").trim();m.effect=String(($("effect-"+id)||{}).value||m.effect||"").trim();m.status="AI檢查中";m.checkMsg="";setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;render();setTimeout(()=>runMethodAiCheck(id),180)}
    function methodReasonChips(m,editable){let causes=usableCauses();if(!causes.length)return '<p class="small">尚未有已確認原因，請先回到原因分析完成向右魚骨圖。</p>';if(!editable){let names=(m.causes||[]).map(cid=>(S.causes.find(c=>c.id===cid)||{}).text).filter(Boolean);return names.length?`<div class="links">${names.map(n=>`<span>${esc(n)}</span>`).join("")}</div>`:'<p class="small">尚未連結原因。</p>'}return `<div class="chips">${causes.map(c=>`<label class="chip"><input type="checkbox" ${(m.causes||[]).includes(c.id)?"checked":""} onchange="toggleMethodCause('${m.id}','${c.id}',this.checked)">${esc(c.text)}</label>`).join("")}</div>`}
    function methodCheckCard(m){let editable=canEditCard(m),status=methodStatus(m),done=methodProcessed(m),hint=methodHint(m),statusCls=done?"ok":(status==="AI 檢查中"?"small":(status==="需要修改說明"?"warn":"small")),checking=m.status==="AI檢查中";return `<article class="card methodCard ${done?'formal':''}">${editable?`<label>方法內容</label><textarea id="methodText-${m.id}" onchange="methodEdit('${m.id}','text',this.value)">${esc(m.text)}</textarea><button class="secondary" onclick="startVoice('methodText-${m.id}')">語音輸入</button>`:`<p>${esc(m.text)}</p>`}${audit(m)}<p class="${statusCls}"><strong>目前檢查狀態：</strong>${esc(status)}</p><p class="small">${esc(hint)}</p><label>對應原因</label>${methodReasonChips(m,editable)}<label>這個方法如何幫助達成決策目標？</label>${editable?`<textarea id="effect-${m.id}" oninput="methodEditSoft('${m.id}','effect',this.value)">${esc(m.effect||"")}</textarea><button class="secondary" onclick="startVoice('effect-${m.id}')">語音輸入</button><div class="row wrap"><button ${checking?"disabled":""} onclick="completeMethodCheck('${m.id}')">${checking?"AI 檢查中":"送交 AI 檢查"}</button><button class="secondary" onclick="skipMethod('${m.id}')">暫不處理／暫不保留</button></div>`:`<p class="surface">${esc(m.effect||"尚未填寫")}</p><div class="readOnlyNote">這是其他成員提出的方法，這裡先以唯讀顯示。</div>`}</article>`}
    function methodLinkEditor(){return `<div class="cardGrid">${S.methods.filter(m=>m.status!=="正式方法"&&m.status!=="暫不納入").map(m=>{let editable=canEditCard(m);return `<article class="card methodCard" draggable="${editable?'true':'false'}" ondragstart="${editable?`drag(event,'method','${m.id}')`:''}"><p>${esc(m.text)}</p>${audit(m)}${editable?'<p class="small">請把這張方法卡拖曳到右側的對應原因區。</p>':'<div class="readOnlyNote">這是其他成員提出的方法，先以唯讀呈現。</div>'}<div class="links">${m.causes.map(cid=>`<span>${esc((S.causes.find(c=>c.id===cid)||{}).text||"原因")} ${editable?`<button class="secondary" onclick="removeCauseLink('${m.id}','${cid}')">移除</button>`:""}</span>`).join("")||'<p class="small">尚未連結原因。</p>'}</div><label>這個方法如何幫助達成決策目標？</label>${editable?`<textarea id="effect-${m.id}" oninput="methodEditSoft('${m.id}','effect',this.value)">${esc(m.effect)}</textarea><button class="secondary" onclick="startVoice('effect-${m.id}')">語音輸入</button>`:`<p class="surface">${esc(m.effect||"尚未填寫")}</p>${lockedTools("method",m.id)}`}</article>`}).join("")}</div><p class="voiceStatus" id="voiceStatus">${voiceHelp(false)}</p>`}
    function methodClassCandidates(){return S.methods.filter(m=>["已完成檢查","已完成對應檢查","正式方法"].includes(m.status)&&m.causes.length&&String(m.effect||"").trim())}
    function ensureDraftMethodClass(){if(!S.draftMethodCats||!S.draftMethodCats.length)S.draftMethodCats=[{id:uid("dmc"),name:"大方法 1"},{id:uid("dmc"),name:"大方法 2"}];if(!S.draftMethodAssignments)S.draftMethodAssignments={}}
    function draftMethodClass(){ensureDraftMethodClass();let methods=methodClassCandidates();return S.draftMethodCats.map(c=>({name:c.name||"未命名大方法",ids:methods.filter(x=>S.draftMethodAssignments[x.id]===c.id).map(x=>x.id)})).filter(g=>g.ids.length)}
    function methodClassSubmitIssue(){if(!hasSpeaker())return "請先在 Step 1 加入活動。";ensureDraftMethodClass();let methods=methodClassCandidates();if(!methods.length)return "請先在 Step 14 完成至少一張方法檢查。";if((S.draftMethodCats||[]).some(c=>!(c.name||"").trim()))return "請先填寫每個大方法名稱。";let unplaced=methods.filter(m=>!S.draftMethodAssignments[m.id]).length;if(unplaced)return `還有 ${unplaced} 張方法卡尚未放入大方法。`;if(!draftMethodClass().length)return "請先建立至少一個有方法卡的大方法。";return ""}
    function methodClassProposalTitle(p){return `${src(p.source).name}整理的方法分類`}
    function methodClassVoteInfo(){return topInfo(S.methodClassProposals||[],S.methodClassVotes||{},"methodClass")}
    function methodClassNeedsRevote(){let info=methodClassVoteInfo();return info.allVoted&&(info.tie||info.own)}
    function methodClassTieAdvice(info=methodClassVoteInfo()){let rows=(info.winners||[]).map(r=>r.item).slice(0,3),fallback="目前有多個方法分類版本同票，還不能決定正式向左魚骨圖分類。請重新看哪一版大方法名稱較清楚、方法歸類較合理，也較能回應原因與支持決策目標，再重新投票。";if(!rows.length)return fallback;let bits=rows.map(p=>{let groups=p.groups||[],names=groups.map(g=>g.name).filter(usefulCompareText).slice(0,2);return names.length?`${methodClassProposalTitle(p)}比較聚焦在${names.map(quoteBrief).join("、")}`:""}).filter(Boolean);return bits.length?`目前有多個方法分類版本同票，還不能決定正式向左魚骨圖分類。${bits.join("；")}。請比較大方法名稱是否清楚、方法歸類是否合理，以及是否能回應原因與支持決策目標，再重新投票。`:fallback}
    function methodClassVoteNotice(){let info=methodClassVoteInfo(),votes=activeVoteCount(S.methodClassVotes||{}),total=memberIds().length||1,progress=`已投票 ${votes}/${total} 人`;if(!S.methodClassProposals.length)return `<p class="small">請先提交至少一版方法分類。</p>`;if(!votes)return `<p class="small">請先投票選出一版方法分類。</p>`;if(info.tie||info.own)return `<p class="warn">${methodClassTieAdvice(info)}</p><p class="small">${progress}</p>`;if(info.clear)return info.allVoted?`<p class="ok">已有唯一最高票，這一版會成為正式向左魚骨圖分類。</p><p class="small">${progress}</p>`:`<p class="ok">目前有一版票數較高，請等待所有組員完成投票。</p><p class="small">${progress}</p>`;return `<p class="small">請完成投票後再進入下一步。${progress}</p>`}
    function addDraftMethodCat(){ensureDraftMethodClass();let el=$("add-draft-method-cat"),v=(el&&el.value.trim())||"";if(!v){showGate("請先輸入大方法名稱。");return}S.draftMethodCats.push({id:uid("dmc"),name:v});render()}
    function renameDraftMethodCat(id,value){ensureDraftMethodClass();let c=S.draftMethodCats.find(x=>x.id===id);if(c)c.name=value;render()}
    function removeDraftMethodCat(id){ensureDraftMethodClass();S.draftMethodCats=S.draftMethodCats.filter(x=>x.id!==id);Object.keys(S.draftMethodAssignments).forEach(k=>{if(S.draftMethodAssignments[k]===id)delete S.draftMethodAssignments[k]});render()}
    function submitMethodClass(){let issue=methodClassSubmitIssue();if(issue){showGate(issue);return}let speaker=actor(),groups=draftMethodClass(),existing=(S.methodClassProposals||[]).find(p=>p.source===speaker);let proposal={id:existing?existing.id:uid("mcp"),source:speaker,groups:plain(groups),updatedAt:Date.now()};S.methodClassProposals=[...(S.methodClassProposals||[]).filter(p=>p.source!==speaker),proposal];newVoteRound("methodClass");S.methodClassConfirmed="";S.outcomeOk=false;S.outcomeNeedsRevision=false;newVoteRound("outcome");S.confirmBy.outcome="";S.feasible="";S.unique="";S.feasibleReason="";S.uniqueReason="";S.solutionTie=false;newVoteRound("solution");S.confirmBy.feasible="";render();showOk("已提交你的方法分類，請到候選方法分類版本區投票。")}
    function applyMethodClassProposal(p){if(!p)return;let ids=new Set((p.groups||[]).flatMap(g=>g.ids||[]));methodClassCandidates().forEach(m=>{m.status="已完成對應檢查";m.big=""});(p.groups||[]).forEach(g=>(g.ids||[]).forEach(mid=>{let m=S.methods.find(x=>x.id===mid);if(m){m.big=g.name||"大方法";m.status="正式方法";setUpdated(m)}}));S.methodsVersion=(S.methodsVersion||0)+1}
    function voteMethodClass(id){if(!hasSpeaker()){remindSpeaker();return}if(!(S.methodClassProposals||[]).some(p=>p.id===id)){showGate("請先選擇一版已提交的方法分類。");return}if(methodClassNeedsRevote())newVoteRound("methodClass");setRoundVote(S.methodClassVotes,actor(),id);if(canFinalizeMethodClass())finalizeMethodClassFromVote();render();if(methodClassVoteInfo().tie)showGate(methodClassTieAdvice())}
    function canFinalizeMethodClass(){let info=methodClassVoteInfo();return (S.methodClassProposals||[]).length>0&&enoughVotes(S.methodClassVotes||{})&&info.clear&&!info.tie}
    function finalizeMethodClassFromVote(){let info=methodClassVoteInfo(),p=info.winners[0]?.item;if(!p)return;applyMethodClassProposal(p);S.methodClassConfirmed=p.id;S.outcomeOk=false;S.outcomeNeedsRevision=false;newVoteRound("outcome");S.confirmBy.outcome="";S.feasible="";S.unique="";S.feasibleReason="";S.uniqueReason="";S.solutionTie=false;newVoteRound("solution");S.confirmBy.feasible="";S.step=16}
    function methodClassProposalCard(p){let revote=methodClassNeedsRevote(),chosen=!revote&&voteValue(S.methodClassVotes||{},actor())===p.id,counts=voteCounts(S.methodClassProposals||[],S.methodClassVotes||{}),official=S.methodClassConfirmed===p.id;return `<article class="card candidateCard ${official?'ok':''}"><div class="meta">${badge(p.source)}<span class="voteCount">${counts[p.id]||0} 票</span>${official?'<span class="badge" style="border-color:#12623d;color:#12623d">正式方法分類</span>':""}</div><h3>${esc(methodClassProposalTitle(p))}</h3>${(p.groups||[]).map(g=>`<div class="surface slim"><strong>${esc(g.name)}</strong><ul>${(g.ids||[]).map(id=>`<li>${esc((S.methods.find(m=>m.id===id)||{}).text||"方法")}</li>`).join("")}</ul></div>`).join("")}<div class="voteBar"><button class="${chosen?'selected':'secondary'}" onclick="voteMethodClass('${p.id}')">${revote?"重新投這一版":chosen?"已投這一版":"投這一版"}</button></div></article>`}
    function resetMethodClass(){S.methodClassProposals=[];newVoteRound("methodClass");S.methodClassConfirmed="";S.draftMethodAssignments={};S.outcomeOk=false;S.outcomeNeedsRevision=false;newVoteRound("outcome");S.confirmBy.outcome="";S.feasible="";S.unique="";S.feasibleReason="";S.uniqueReason="";S.solutionTie=false;newVoteRound("solution");S.confirmBy.feasible=""}
    function methodConfirmCard(m){let pass=m.causes.length&&m.effect.trim(),editable=canEditCard(m);return `<article class="card ${pass?'':'needs'}"><p>${esc(m.text)}</p>${audit(m)}<p class="small">對應原因：${m.causes.length}；支持目標說明：${m.effect.trim()?"已填":"未填"}</p>${editable?`<label>大方法名稱</label><input id="big-${m.id}" value="${esc(m.big)}" oninput="methodEditSoft('${m.id}','big',this.value)" placeholder="例如：分工記錄、溝通約定"><button class="secondary" onclick="startVoice('big-${m.id}')">語音輸入</button><div class="row wrap"><button ${pass?"":"disabled"} onclick="formal('${m.id}')">放進魚骨圖</button><button class="secondary" onclick="skipMethod('${m.id}')">暫不納入</button><button class="secondary" onclick="removeMethod('${m.id}')">移除</button></div>${pass?"":'<p class="warn">請先完成 Step 14 的原因對應與支持目標說明。</p>'}`:lockedTools("method",m.id)}</article>`}
    function formal(id){let m=S.methods.find(x=>x.id===id);if(!m)return;if(!m.big.trim()){alert("請先輸入大方法名稱，不能出現未命名大方法。");return}m.status="正式方法";setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;render()}
    function moveBackMethod(id){let m=S.methods.find(x=>x.id===id);if(m&&canEditCard(m)){m.status="草稿";setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1}render()}
    function skipMethod(id){let m=S.methods.find(x=>x.id===id);if(!m||!canEditCard(m)){showGate("只能處理自己提出的方法。");return}m.status="暫不納入";setUpdated(m);S.methodsVersion=(S.methodsVersion||0)+1;resetMethodClass();maybeAdvanceAfterMethodCheck();render()}
    function removeMethod(id){let m=S.methods.find(x=>x.id===id);if(!m||!canEditCard(m)){showGate("只能刪除自己提出的方法。");return}if(confirm("移除此方法？")){S.methods=S.methods.filter(x=>x.id!==id);S.deletedMethodIds=unionIds(S.deletedMethodIds,[id]);S.methodsVersion=(S.methodsVersion||0)+1;resetMethodClass();render()}}
    function togglePriority(id,on){S.priorityOpen=true;S.priority=on?unionIds(S.priority||[],[id]):(S.priority||[]).filter(x=>x!==id);render()}
    function usableCauses(){return S.causes.filter(c=>c.status==="已確認為原因")}
    function formalMethods(){return S.methods.filter(m=>m.status==="正式方法"&&m.big.trim())}
    function clampText(t,n=32){t=String(t||"");return t.length>n?t.slice(0,n-1)+"…":t}
    function fishGroups(side){if(side==="right")return S.cats.map(cat=>({name:cat.name,items:usableCauses().filter(c=>c.catId===cat.id).map(c=>c.text)})).filter(g=>g.items.length);let groups={};formalMethods().forEach(m=>{(groups[m.big]||(groups[m.big]=[])).push(m.text)});return Object.keys(groups).map(k=>({name:k,items:groups[k]}))}
    function fishList(groups,emptyName,emptyItem){return groups&&groups.length?groups:[{name:emptyName,items:[emptyItem]}]}
    function fishData(direction,provided={}){let isRight=direction==="right",groups=provided.groups||fishGroups(direction),head=provided.head||(isRight?(S.problem||S.selected||"尚未確認主要問題"):(S.goal||"尚未建立決策目標"));return {direction,groups:fishList(groups,isRight?"尚未整理大要因":"尚未整理大方法",isRight?"尚未放入原因":"尚未放入方法"),head,title:provided.title||(isRight?"向右魚骨圖：找原因":"向左魚骨圖：找方法"),headLabel:provided.headLabel||(isRight?"魚頭＝主要問題":"魚頭＝決策目標"),bigLabel:provided.bigLabel!==undefined?provided.bigLabel:(isRight?"大要因":"大方法"),smallLabel:provided.smallLabel!==undefined?provided.smallLabel:(isRight?"具體原因":"具體方法")}}
    function fishTitleText(text,kind){let s=String(text||"").trim().replace(/\s+/g,"");if(!s)return "";if(/^(大骨|原因卡|大方法|方法卡)：/.test(s))return s;let rules=[[/不知道.*判斷.*重要|判斷.*重要|重要性/,"重要性判斷困難"],[/安排.*先後|先後.*順序|優先順序|優先.*不清/,"任務優先順序不清"],[/作業.*報告.*考試.*集中|任務.*集中|很多.*任務/,"任務集中"],[/先做.*簡單|想做.*事情|比較想做/,"偏好簡單任務"],[/截止.*近|期限.*近|拖到最後/,"急件被拖延"],[/低估.*時間|低估.*花費|需要.*更多時間|時間.*不夠|時間.*不足/,"時間估計不足"],[/作業.*(無法|不能|沒辦法).*準時.*(完成|繳交)/,"作業未準時完成"],[/減少.*忘記.*期限.*準時.*完成/,"準時完成作業"],[/忘記.*期限/,"忘記期限"],[/不同平台.*(分散|訊息)/,"訊息分散"],[/放學後.*手機|滑手機|被手機.*吸引/,"手機分心"],[/桌面.*(雜物|太多)/,"桌面雜亂"],[/聲音.*分心|太吵|噪音/,"環境干擾"],[/提醒.*工具|沒有提醒/,"缺少提醒"],[/提醒.*太晚/,"提醒太晚"],[/每天.*查看.*平台/,"每日查看平台"],[/期限.*清單|清單.*期限/,"整理期限清單"],[/建立.*提醒|提醒.*流程/,"建立提醒流程"],[/先寫.*急|最急.*作業/,"先做急件"],[/25.*分鐘|番茄鐘|專注時間/,"設定專注時間"],[/清出.*桌面|作業區/,"整理作業區"],[/安靜時段|家人.*安靜/,"約定安靜時段"],[/計畫|學習計畫/,"建立學習計畫"],[/溝通/,"溝通協調"],[/分工/,"分工安排"],[/環境/,"學習環境"],[/時間/,"時間管理"],[/提醒/,"提醒機制"],[/作業/,"作業處理"],[/手機/,"手機使用"]];for(let [re,label] of rules)if(re.test(s))return label;let f=focusInfo([s]);if(f.label&&f.label!=="問題焦點")return f.label;let parts=s.split(/[，。；、,.!?！？：:]/).filter(Boolean),p=(parts.find(x=>x.length>=2)||s).replace(/^(因為|所以|可以|透過|讓|希望|想要|我們|學生|小組|請|要|把|將|容易|常常)/,"").replace(/(的情況|的問題|這件事|一件事)$/,"");if(p.length<=10)return p;if(kind==="head"&&p.length<=14)return p;let m=p.match(/[\u4e00-\u9fffA-Za-z0-9]{2,}(管理|不足|不佳|拖延|分心|干擾|困難|流程|計畫|提醒|環境|準備|溝通|合作|期限|時間|手機|作業|方法|原因|行動|步驟|順序|判斷)/);if(m&&m[0].length<=12)return m[0];if(/cause/i.test(kind))return "待釐清原因";if(/method/i.test(kind))return "待整理方法";return "待整理問題"}
    function fishDisplayGroups(groups,kind){return groups.map(g=>({name:fishTitleText(g.name,kind==="method"?"methodBig":"causeBig"),items:(g.items||[]).map(it=>fishTitleText(it,kind==="method"?"method":"cause"))}))}
